// Scoreboard — AHB-aware reference model
// ════════════════════════════════════════════════════════════
class ahb_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(ahb_scoreboard)

  uvm_analysis_imp #(ahb_transaction, ahb_scoreboard) analysis_export;

  // Reference memory — same shape as the DUT
  logic [31:0] memory [0:31];

  function new(string name="ahb_scoreboard", uvm_component parent=null);
    super.new(name, parent);
    analysis_export = new("analysis_export", this);
    foreach (memory[i]) memory[i] = 32'h0;  // match DUT reset
  endfunction

  // ---- alignment / size legality (matches DUT) -----------------------
  function bit is_legal_access(logic [2:0] hsize, logic [31:0] haddr);
    case (hsize)
      3'b000: return 1'b1;                  // byte: always aligned
      3'b001: return (haddr[0]   == 1'b0);  // half: 2-byte aligned
      3'b010: return (haddr[1:0] == 2'b00); // word: 4-byte aligned
      default: return 1'b0;                 // unsupported size
    endcase
  endfunction

  // ---- write-data lane steering (matches DUT) ------------------------
  function logic [31:0] merge_write(logic [31:0] cur,
                                    logic [31:0] wdata,
                                    logic [2:0]  hsize,
                                    logic [31:0] haddr);
    logic [31:0] r;
    r = cur;
    case (hsize)
      3'b000: begin // byte
        case (haddr[1:0])
          2'b00: r[7:0]   = wdata[7:0];
          2'b01: r[15:8]  = wdata[7:0];
          2'b10: r[23:16] = wdata[7:0];
          2'b11: r[31:24] = wdata[7:0];
        endcase
      end
      3'b001: begin // half
        if (haddr[1] == 1'b0) r[15:0]  = wdata[15:0];
        else                  r[31:16] = wdata[15:0];
      end
      3'b010: r = wdata; // word
    endcase
    return r;
  endfunction

  // ---- read-data lane extraction (matches DUT) -----------------------
  function logic [31:0] expected_read(logic [31:0] cur,
                                      logic [2:0]  hsize,
                                      logic [31:0] haddr);
    logic [31:0] r;
    r = '0;
    case (hsize)
      3'b000: begin
        case (haddr[1:0])
          2'b00: r[7:0] = cur[7:0];
          2'b01: r[7:0] = cur[15:8];
          2'b10: r[7:0] = cur[23:16];
          2'b11: r[7:0] = cur[31:24];
        endcase
      end
      3'b001: begin
        if (haddr[1] == 1'b0) r[15:0] = cur[15:0];
        else                  r[15:0] = cur[31:16];
      end
      3'b010: r = cur;
    endcase
    return r;
  endfunction

  virtual function void write(ahb_transaction trans);
    logic [4:0]  idx;
    logic [31:0] expected;

    // Filter 1: skip IDLE/BUSY — only NONSEQ/SEQ are real transfers.
    if (!(trans.HTRANS == 2'b10 || trans.HTRANS == 2'b11)) return;

    // Filter 2: skip un-selected transfers.
    if (!trans.HSEL) return;

    // Filter 3: skip incomplete transfers (HREADYOUT=0 means wait/ERR1).
    //   The monitor already gates on this, but defend in depth.
    if (!trans.HREADYOUT) return;

    // Filter 4: skip error responses — DUT does not commit writes
    //   nor deliver valid read data when HRESP=1.
    if (trans.HRESP) return;

    // Filter 5: skip illegal accesses (DUT will have flagged these as
    //   errors anyway, but if HRESP somehow looked clean, still skip).
    if (!is_legal_access(trans.HSIZE, trans.HADDR)) return;
$display("[%0t] SCB: %s HADDR=0x%08h size=%b HWDATA=0x%08h HRDATA=0x%08h",
         $time, trans.HWRITE ? "WR" : "RD",
         trans.HADDR, trans.HSIZE, trans.HWDATA, trans.HRDATA);

    idx = trans.HADDR[6:2];

    if (trans.HWRITE) begin
      // Mirror the DUT's lane-steered write
      memory[idx] = merge_write(memory[idx], trans.HWDATA,
                                trans.HSIZE, trans.HADDR);
    end
    else begin
      // Compute expected read with the same lane extraction the DUT does
      expected = expected_read(memory[idx], trans.HSIZE, trans.HADDR);
      if (trans.HRDATA !== expected) begin
        `uvm_error("SCB",
          $sformatf("Read mismatch @0x%08h size=%0b: expected 0x%08h got 0x%08h",
                    trans.HADDR, trans.HSIZE, expected, trans.HRDATA))
      end
    end
  endfunction
endclass

