// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

class ahb_coverage extends uvm_subscriber #(ahb_transaction);
  `uvm_component_utils(ahb_coverage)

  // Local sampled fields
  bit        hsel;
  bit [31:0] haddr;
  bit [1:0]  htrans;
  bit [2:0]  hsize;

  covergroup cov_transaction;
    option.per_instance = 1;

    cp_hsel: coverpoint hsel {
      bins not_selected = {0};
      bins selected     = {1};
    }

    cp_haddr: coverpoint haddr {
      bins low_addr  = {[0:31]};
      bins high_addr = {[64:127]};
    }

    cp_htrans: coverpoint htrans {
      bins idle   = {2'b00};
      bins busy   = {2'b01};
      bins nonseq = {2'b10};
      bins seq    = {2'b11};
    }

    cp_hsize: coverpoint hsize {
      bins byte_access = {3'b000};
      bins half_access = {3'b001};
      bins word_access = {3'b010};
    }

    cross_haddr_hsize: cross cp_haddr, cp_hsize;

  endgroup

  function new(string name="ahb_coverage", uvm_component parent=null);
    super.new(name, parent);
    cov_transaction = new();
  endfunction

  virtual function void write(ahb_transaction t);
  hsel   = t.HSEL;
  haddr  = t.HADDR;
  htrans = t.HTRANS;
  hsize  = t.HSIZE;

  cov_transaction.sample();
endfunction

endclass

